CREATE TABLE import_jobs (id TEXT NOT NULL PRIMARY KEY, bucket TEXT NOT NULL, key TEXT NOT NULL, source_type TEXT NOT NULL, request_fingerprint TEXT NOT NULL, client_token TEXT, state TEXT NOT NULL, phase TEXT NOT NULL, attempts INTEGER NOT NULL, next_attempt_at @TZ@ NOT NULL, locked_by TEXT, locked_until @TZ@, claim_epoch BIGINT NOT NULL DEFAULT 0, providers_observed BIGINT NOT NULL, pin_nodes_processed BIGINT NOT NULL, pin_bytes_processed BIGINT NOT NULL, downloaded_bytes BIGINT NOT NULL, download_total BIGINT, ipfs_add_bytes BIGINT NOT NULL, logical_size BIGINT, entries_processed BIGINT NOT NULL, entries_succeeded BIGINT NOT NULL, entries_failed BIGINT NOT NULL, decompressed_bytes BIGINT NOT NULL, final_cid TEXT, failure_code TEXT, failure_message TEXT, created_at @TZ@ NOT NULL, updated_at @TZ@ NOT NULL, completed_at @TZ@, CHECK(source_type IN ('cid','url')), CHECK(state IN ('queued','running','completed','failed','superseded')), CHECK(phase IN ('queued','discovering_providers','pinning_local','downloading','adding_to_ipfs','inspecting','decompressing','publishing')), CHECK(attempts>=0), CHECK(claim_epoch>=0), CHECK(providers_observed>=0), CHECK(pin_nodes_processed>=0), CHECK(pin_bytes_processed>=0), CHECK(downloaded_bytes>=0), CHECK(download_total>=0), CHECK(ipfs_add_bytes>=0), CHECK(logical_size>=0), CHECK(entries_processed>=0), CHECK(entries_succeeded>=0), CHECK(entries_failed>=0), CHECK(decompressed_bytes>=0));
CREATE TABLE import_job_requests (job_id TEXT NOT NULL PRIMARY KEY, source_value TEXT NOT NULL, object_content_type TEXT, metadata_json TEXT NOT NULL, tags_json TEXT NOT NULL, pin_decision_json TEXT, zip_intent_json TEXT, decompress_prefix TEXT, root_capture_json TEXT, FOREIGN KEY(job_id) REFERENCES import_jobs(id) ON DELETE CASCADE);
CREATE TABLE import_destinations (bucket TEXT NOT NULL, key TEXT NOT NULL, generation BIGINT NOT NULL, owner_job_id TEXT, updated_at @TZ@ NOT NULL, mutation_id TEXT, mutation_prefix TEXT, CONSTRAINT pk_import_destinations PRIMARY KEY(bucket,key), FOREIGN KEY(bucket) REFERENCES buckets(name) ON DELETE CASCADE, FOREIGN KEY(owner_job_id) REFERENCES import_jobs(id) ON DELETE SET NULL, CHECK(generation>=1));
CREATE TABLE import_prefix_claims (job_id TEXT NOT NULL, bucket TEXT NOT NULL, prefix TEXT NOT NULL, claim_order BIGINT NOT NULL, CONSTRAINT pk_import_prefix_claims PRIMARY KEY(job_id,bucket,prefix), FOREIGN KEY(job_id) REFERENCES import_jobs(id) ON DELETE CASCADE, FOREIGN KEY(bucket) REFERENCES buckets(name) ON DELETE CASCADE, CHECK(claim_order>=0));
CREATE TABLE import_job_targets (job_id TEXT NOT NULL, bucket TEXT NOT NULL, key TEXT NOT NULL, expected_generation BIGINT NOT NULL, kind TEXT NOT NULL, CONSTRAINT pk_import_job_targets PRIMARY KEY(job_id,bucket,key), FOREIGN KEY(job_id) REFERENCES import_jobs(id) ON DELETE CASCADE, FOREIGN KEY(bucket) REFERENCES buckets(name) ON DELETE CASCADE, CHECK(expected_generation>=1), CHECK(kind IN ('archive','extracted')));
CREATE TABLE import_job_results (job_id TEXT NOT NULL, sequence BIGINT NOT NULL, key TEXT NOT NULL, cid TEXT, size BIGINT, error_code TEXT, error_message TEXT, CONSTRAINT pk_import_job_results PRIMARY KEY(job_id,sequence), FOREIGN KEY(job_id) REFERENCES import_jobs(id) ON DELETE CASCADE, CHECK(sequence>=0), CHECK(size>=0), CHECK((cid IS NOT NULL AND size IS NOT NULL AND error_code IS NULL AND error_message IS NULL) OR (cid IS NULL AND size IS NULL AND error_code IS NOT NULL AND error_message IS NOT NULL)));
CREATE UNIQUE INDEX uq_import_jobs_bucket_key_client_token ON import_jobs(bucket,key,client_token);
CREATE INDEX idx_import_jobs_state_next_attempt_locked ON import_jobs(state,next_attempt_at,locked_until);
CREATE INDEX idx_import_jobs_state_completed_at ON import_jobs(state,completed_at);
CREATE INDEX idx_import_destinations_owner_job ON import_destinations(owner_job_id);
CREATE INDEX idx_import_prefix_claims_bucket_prefix ON import_prefix_claims(bucket,prefix);
CREATE INDEX idx_import_job_targets_bucket_key ON import_job_targets(bucket,key);
CREATE INDEX idx_import_job_results_job_sequence ON import_job_results(job_id,sequence);
CREATE INDEX idx_import_destinations_active_mutation ON import_destinations(bucket,mutation_id,key);
CREATE INDEX idx_import_destinations_mutation_prefix ON import_destinations(bucket,mutation_prefix,key);
CREATE TABLE standard_mutation_leases (bucket TEXT NOT NULL, key TEXT NOT NULL, mutation_id TEXT NOT NULL, generation BIGINT NOT NULL, lease_until @LEASE_TIME@ NOT NULL, PRIMARY KEY(bucket,key), FOREIGN KEY(bucket,key) REFERENCES import_destinations(bucket,key) ON DELETE CASCADE);
